  const props=[],free=(x,z,p)=>clear(x,z,p)&&!props.some(q=>Math.abs(q.x-x)<p+1.4&&Math.abs(q.z-z)<p+1.4)&&!crates.some(q=>Math.abs(q.x-x)<p+1.4&&Math.abs(q.z-z)<p+1.4);
