function rayObs(W2,ox,oy,oz,dx,dy,dz,max){ let best=max,step=W2.GR*.5,seen=new Set(); for(let d=0;d<=max;d+=step){ const a=W2.near(ox+dx*d,oz+dz*d); for(const o of a){ if(seen.has(o)||o.soft&&d>60) continue; seen.add(o); let t0=0,t1=best,ok=true; for(const [p,v,a0,a1] of [[ox,dx,o.x0,o.x1],[oy,dy,o.y0,o.y1],[oz,dz,o.z0,o.z1]]){ if(Math.abs(v)<1e-6){ if(p<a0||p>a1){ ok=false; break; } } else { let q0=(a0-p)/v,q1=(a1-p)/v; if(q0>q1){ const q=q0; q0=q1; q1=q; } t0=Math.max(t0,q0); t1=Math.min(t1,q1); if(t0>t1){ ok=false; break; } } } if(ok&&t0<best) best=t0; } if(d>best) break; } return best; }
